script:
country_event = {
	id = distar.5052
	hide_window = yes

	is_triggered_only = yes

	trigger = {
		NOR = {
			has_global_flag = cache_returned
			any_controlled_ship = {
				has_ship_flag = enigmatic_cache_ship
				exists = orbit
				exists = orbit.owner
				orbit.owner = {
					is_researching_special_project = ENIGMATIC_CACHE_PROJECT
				}
			}
		}
	}

	immediate = {
	# Runs check to remove enigmatic_cache_in_orbit modifier
		random_controlled_ship = {
			limit = {
				has_ship_flag = enigmatic_cache_ship
				exists = orbit
			}
			orbit = {
				carrier_event = { id = distar.5056 days = 2 }
				save_event_target_as = cache_present_location
				if = {
					limit = {
						exists = owner
					}
					owner = { save_event_target_as = enigmatic_cache_present_host }
				}
				# sets 'scanned' planet flag on present location
				if = {
					limit = {
						NOT = {
							has_carrier_flag = has_been_scanned
						}
					}
					set_carrier_flag = has_been_scanned
				}
			}
		}
		# Cache searches for new location:
		# Tries to find a player controlled country
		if = {
			limit = {
				any_playable_country = {
					is_ai = no
					is_at_war = no
					NOR = {
						is_hostile = root
						root = { is_hostile = prev }
					}
					any_owned_planet = {
						NOT = { has_carrier_flag = has_been_scanned }
					}
				}
			}
			random_controlled_ship = {
				limit = {
					has_ship_flag = enigmatic_cache_ship
				}
				solar_system = {
					closest_system = {
						use_bypasses = yes
						limit = {
							exists = owner
							owner = {
								is_ai = no
								is_country_type = default
								is_at_war = no
								NOR = {
									is_hostile = root
									root = { is_hostile = prev }
								}
							}
							NOT = {
								any_fleet_in_system = {
									exists = owner
									owner = {
										is_hostile = root
									}
								}
							}
							any_system_planet = {
								is_colony = yes
								NOT = { has_carrier_flag = has_been_scanned }
							}
						}
						random_system_planet = {
							limit = {
								is_colony = yes
								NOT = { has_carrier_flag = has_been_scanned }
							}
							save_event_target_as = new_location
						}
					}
				}
				auto_move_to_planet = {
					target = event_target:new_location
					clear_auto_move_on_arrival = no	# distar. sets a new auto move target
				}
			}
		}
		else_if = {
			limit = {
				any_playable_country = {
					is_at_war = no
					NOR = {
						is_hostile = root
						root = { is_hostile = prev }
					}
					any_owned_planet = {
						NOT = { has_carrier_flag = has_been_scanned }
					}
				}
			}
			random_controlled_ship = {
				limit = {
					has_ship_flag = enigmatic_cache_ship
				}
				solar_system = {
					closest_system = {
						use_bypasses = yes
						limit = {
							exists = owner
							owner = {
								is_country_type = default
								is_at_war = no
								NOR = {
									is_hostile = root
									root = { is_hostile = prev }
								}
							}
							any_system_planet = {
								is_colony = yes
								NOT = { has_carrier_flag = has_been_scanned }
							}
						}
						random_system_planet = {
							limit = {
								is_colony = yes
								NOT = { has_carrier_flag = has_been_scanned }
							}
							#set_carrier_flag = has_been_scanned
							save_event_target_as = new_location
						}
					}
				}
				auto_move_to_planet = {
					target = event_target:new_location
					clear_auto_move_on_arrival = no	# istar. sets a new auto move target
				}
			}
		}

		# Attempts to move again later if no suitable location
		else = {
			country_event = { id = distar.5052 days = 100 }
		}
		# Set flag if cache is moving to planet within same country
		if = {
			limit = {
				exists = event_target:new_location
				exists = event_target:enigmatic_cache_present_host
